-- Future SELECT-only checks after separately approved exact five-file apply.
-- No real account, input, eligibility, assignment or result smoke writes.
BEGIN TRANSACTION READ ONLY;
SELECT count(*) AS ledger_count,max(version) AS ledger_tip FROM supabase_migrations.schema_migrations;
SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'oid',p.oid,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig,'body_sha256',encode(extensions.digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')) ORDER BY p.oid::regprocedure::text) AS functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f';
SELECT jsonb_build_object('training_setup',(SELECT count(*) FROM public.athlete_training_setup),'eligibility',(SELECT count(*) FROM public.private_programme_alpha_eligibility),'zone_inputs',(SELECT count(*) FROM public.athlete_running_zone2_inputs),'frozen_targets',(SELECT count(*) FROM public.programme_occurrence_zone2_targets),'quality_inputs',(SELECT count(*) FROM public.athlete_running_quality_inputs),'historical_nonnull_receipts',(SELECT count(*) FROM public.programme_slot_outcomes WHERE completion_request_sha256 IS NOT NULL)) AS expected_empty;
SELECT c.relname,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,c.relacl FROM pg_class c WHERE c.oid=ANY(ARRAY['public.athlete_training_setup'::regclass,'public.private_programme_alpha_eligibility'::regclass,'public.athlete_running_zone2_inputs'::regclass,'public.programme_occurrence_zone2_targets'::regclass,'public.athlete_running_quality_inputs'::regclass]) ORDER BY c.relname;
SELECT t,role,has_table_privilege(role,'public.'||t,'SELECT') AS select_allowed,has_table_privilege(role,'public.'||t,'INSERT') AS insert_allowed,has_table_privilege(role,'public.'||t,'UPDATE') AS update_allowed,has_table_privilege(role,'public.'||t,'DELETE') AS delete_allowed FROM unnest(ARRAY['athlete_training_setup','private_programme_alpha_eligibility','athlete_running_zone2_inputs','programme_occurrence_zone2_targets','athlete_running_quality_inputs']) t CROSS JOIN unnest(ARRAY['anon','authenticated','service_role']) role ORDER BY t,role;
SELECT tablename,policyname,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename=ANY(ARRAY['athlete_training_setup','private_programme_alpha_eligibility','athlete_running_zone2_inputs','programme_occurrence_zone2_targets','athlete_running_quality_inputs']) ORDER BY tablename,policyname;
SELECT tgrelid::regclass,tgname,pg_get_triggerdef(oid) FROM pg_trigger WHERE NOT tgisinternal AND (tgrelid='public.programme_occurrence_zone2_targets'::regclass OR tgrelid='public.training_session_records'::regclass OR tgname='completion_receipt_guard') ORDER BY tgrelid::regclass::text,tgname;
COMMIT;
